def policy(obs, P):
    cos1 = obs[0]
    sin1 = obs[1]
    cos2 = obs[2]
    sin2 = obs[3]
    v1 = obs[4]
    v2 = obs[5]
    if sin1 < P['sin1_0_thr'] and v2 > P['v2_0_low'] and v2 < P['v2_0_high']:
        if v1 < P['v1_0_thr'] or sin1 < P['sin1_0_thr2']:
            return 1
    if v1 < P['v1_thr']:
        if sin1 < P['sin1_neg_thr'] and v2 < P['v2_low']:
            return 0
        return 2
    else:
        if v2 > P['v2_pos_thr']:
            return 2
        if sin1 > P['sin1_pos_thr'] and v2 > P['v2_mid_thr']:
            return 2
        score = P['w_sin1']*sin1 + P['w_v2']*v2 + P['w_cos1']*cos1 + P['w_v1']*v1
        if score > P['score_thr']:
            return 2
        return 0
